#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int countGoodRectangles(vector<vector<int>>& rectangles) {
        int max_len = 0;
        int ans = 0;
        for (const auto& r : rectangles) {
            int side = min(r[0], r[1]);
            if (side > max_len) {
                max_len = side;
                ans = 1;
            } else if (side == max_len) {
                ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public int countGoodRectangles(int[][] rectangles) {
        int maxLen = 0;
        int ans = 0;
        for (int[] r : rectangles) {
            int side = Math.min(r[0], r[1]);
            if (side > maxLen) {
                maxLen = side;
                ans = 1;
            } else if (side == maxLen) {
                ans++;
            }
        }
        return ans;
    }
}

/**
 * @param {number[][]} rectangles
