var countGoodRectangles = function(rectangles) {
    let maxLen = 0;
    let ans = 0;
    for (const [l, w] of rectangles) {
        const side = Math.min(l, w);
        if (side > maxLen) {
            maxLen = side;
            ans = 1;
        } else if (side == maxLen) {
            ans++;
        }
    }
    return ans;
};
